-- El juego de caracteres se fija SIEMPRE: el cliente `mysql` lo toma del entorno y en un
-- contenedor sin locale eso es latin1, que convierte cada tilde en mojibake sin dar error.
SET NAMES utf8mb4;
-- Fotos de puntos de interés (poi-images.js)
UPDATE points_of_interest SET image_url = 'https://commons.wikimedia.org/wiki/Special:FilePath/Cabezo_del_Plomo_-_Megalitismo._Sepulgro_tipo_Tholos.jpg?width=1280', source = 'Catálogo de Monumentos de la Región de Murcia (datos abiertos de la CARM, nexo.carm.es, registro n.º 5611), consultado el 2026-08-22, de donde salen el hecho y la coordenada. Declaración BIC corroborada en Wikidata (Q43175856, P808 = RI-55-0000172, Zona Arqueológica), que aquí es SUSTITUTO del boletín: el catálogo no cita la norma de declaración y no se ha podido llegar a ella (el índice de anuncios del BORM da entrada por la ficha de la norma, y esta declaración es de patrimonio, no de medio ambiente). OpenStreetMap (way/669396011, ODbL) coincide en la posición dentro de 70 m y añade la fecha de inscripción, 2006-03-24; Wikimedia Commons (foto: Bertobarc90, CC BY-SA 4.0)' WHERE slug = 'cabezo-del-plomo' AND park_id = (SELECT id FROM parks WHERE slug = 'sierra-de-las-moreras');
UPDATE points_of_interest SET image_url = 'https://commons.wikimedia.org/wiki/Special:FilePath/Punto_Geodesico_Morron_Blanco.jpg?width=1280', source = 'Vértice geodésico 97654 de la Red ROI del IGN. Los datos (código, altitud 489,4 m y coordenada) se han leído en Wikidata (Q115506724: P528, P2044, P625), que aquí es SUSTITUTO de la fuente primaria: los dos hosts del IGN que la sirven —api-features.ign.es y datos-geodesia.ign.es, este último con la reseña oficial en https://datos-geodesia.ign.es/Red_Geodesica/Hoja0976/097654.pdf— quedan fuera de la política de egreso de esta sesión (403 en el CONNECT, comprobado con npm run red:check). OpenStreetMap (node/948499834, ODbL) confirma posición y altitud citando la misma Red ROI. La cota sin nombre de 493 m es OpenStreetMap (node/11390346158); Wikimedia Commons (foto: MarkJessop1, CC BY-SA 4.0)' WHERE slug = 'morron-blanco' AND park_id = (SELECT id FROM parks WHERE slug = 'sierra-de-las-moreras');
